def _is_safe_url(url, host):
    # Normalize and validate input
    if not url:
        return False
    url = url.strip()
    if not url:
        return False

    # Reject URLs that start with control characters anywhere
    for char in url:
        if unicodedata.category(char)[0] == 'C':
