    # Treat any url with three or more leading slashes as unsafe.
    if url.startswith('///'):
        return False
    # Also reject protocol-relative URLs (starting with // but not ///)
    if url.startswith('//'):
        return False

    url_info = urlparse(url)

    # Forbid URLs with a scheme but without a hostname (e.g., 'http:///example.com')
    if url_info.scheme and not url_info.netloc:
        return False

    # Only allow http/https schemes if a scheme is present
    if url_info.scheme and url_info.scheme not in ['http', 'https']:
        return False

    # If there's a netloc, it must exactly match the host (case-insensitive)
    if url_info.netloc:
        # Normalize host and netloc to lowercase for comparison
        if url_info.netloc.lower() != host.lower():
