        # Must have a valid scheme if netloc is present
        if not url_info.scheme:
            return False
    else:
        # No netloc: must be a relative path (no scheme allowed)
        if url_info.scheme:
            return False

    # Final safety: ensure the URL does not start with '/' if we're relying on relative paths?
    # Actually, relative paths can start with '/', so we allow that.
    # The key is: no external netloc, no unsafe scheme, no control chars, no // prefix.
