func Clean(p string) string {
	// Reject empty paths
	if p == "" {
		return ""
	}

	// Clean the path using filepath.Clean for proper path normalization
	cleaned := filepath.Clean(filepath.FromSlash(p))

	// Check if the cleaned path tries to go above the current directory
	// by ensuring it doesn't start with '..' or contain '/../'
	if strings.HasPrefix(cleaned, "..") || strings.Contains(cleaned, "/../") || strings.HasSuffix(cleaned, "/..") {
		return ""
	}

	// Ensure the path is relative (doesn't start with / or drive letter on Windows)
	if len(cleaned) > 0 && (cleaned[0] == '/' || cleaned[0] == '\\') {
		return ""
	}

	// On Windows, also check for drive letters
	if runtime.GOOS == "windows" {
		if len(cleaned) >= 2 && cleaned[1] == ':' {
			return ""
		}
	}

	return cleaned
}

