	checkGitDir := func(p string) bool {
		l := len(p)
		if l < 4 {
			return false
		}
		// Ends with "/.git" or exactly ".git"
		if p == ".git" || (l > 4 && p[l-5:l] == "/.git") {
			return true
		}
		// Contains "/.git/"
		if strings.Contains(p, "/.git/") {
			return true
		}
		// Windows-specific: ".git." treated as ".git"
		if l >= 5 && (p == ".git." || (l > 5 && p[l-6:l] == "/.git.")) {
			return true
		}
		if strings.Contains(p, "/.git./") {
			return true
		}
		return false
	}

	return checkGitDir(lowerPath)
}

