func isRepositoryGitPath(path string) bool {
	// Clean the path to handle redundant separators and relative components
	cleanedPath := filepath.Clean(path)

	// Split the path into components
	components := strings.Split(cleanedPath, string(os.PathSeparator))
	if len(components) == 0 {
		return false
	}

	// Handle the case where path starts with separator (absolute path)
	// strings.Split will create an empty first element
	startIndex := 0
	if cleanedPath != "" && os.IsPathSeparator(cleanedPath[0]) {
		startIndex = 1
	}

	// Also check the original path with backslashes for Windows compatibility
	var altComponents []string
	if os.PathSeparator != '/' {
		altComponents = strings.Split(path, "/")
	} else if strings.Contains(path, "\\") {
		altComponents = strings.Split(path, "\\")
	}

	checkComponent := func(component string) bool {
		// Check for exact ".git" match
		if component == ".git" {
			return true
		}
		// Check for ".git." (Windows treats this as ".git")
		if component == ".git." {
			return true
		}
		return false
	}

	// Check components from the cleaned path
	for i := startIndex; i < len(components); i++ {
		if components[i] != "" && checkComponent(components[i]) {
			return true
		}
	}

	// Check alternative components if they exist
	if altComponents != nil {
		for _, component := range altComponents {
			if component != "" && checkComponent(component) {
				return true
			}
		}
	}

