import { Address4, Address6 } from 'ip-address';

export default (ip) => {
  try {
    // Try IPv4 first
    const addr4 = new Address4(ip);
    if (addr4.isValid()) {
      // Check if IPv4 address is in any reserved/private range
      return addr4.isPrivate() || 
             addr4.isLinkLocal() || 
             addr4.isLoopback() || 
             addr4.isMulticast() ||
             ip === '255.255.255.255' ||
             // Documentation/test networks
             addr4.subnetMask === '255.255.255.0' && 
             (addr4.startingAddress().address.match(/^192\.0\.2\./) ||
              addr4.startingAddress().address.match(/^198\.51\.100\./) ||
              addr4.startingAddress().address.match(/^203\.0\.113\./));
    }

    // Try IPv6
    const addr6 = new Address6(ip);
    if (addr6.isValid()) {
      return addr6.isPrivate() ||
             addr6.isLinkLocal() ||
             addr6.isLoopback() ||
             addr6.isMulticast() ||
             // IPv6 documentation range
             addr6.address.match(/^2001:db8:/i) ||
             ip === '::' ||
             ip === '::1';
    }

    // Invalid IP format
    return false;
  } catch (e) {
    return false;
  }
};

