	const repoPrefix = "/api/v1/repos/"
	if strings.HasPrefix(path, repoPrefix) {
		parts := strings.Split(strings.TrimPrefix(path, repoPrefix), "/")
		if len(parts) >= 2 {
			owner := parts[0]
			repo := parts[1]
			// Check if the authenticated user has access to this repository
			hasAccess, err := c.RepoAccess(context.Background(), u, owner, repo)
			if err != nil {
				return nil, fmt.Errorf("error checking repository access: %w", err)
			}
			if !hasAccess {
				return nil, errors.New("user not authorized for this repository")
			}
		}
	}

	return &library.User{
		Name:  &u,
		Token: &token,
	}, nil
}

