func validateVolume(src *v1.GitRepoVolumeSource) error {
	if err := validateNonFlagArgument(src.Repository, "repository"); err != nil {
		return err
	}
	if err := validateNonFlagArgument(src.Revision, "revision"); err != nil {
		return err
	}
	if err := validateNonFlagArgument(src.Directory, "directory"); err != nil {
		return err
	}
	if (src.Revision != "") && (src.Directory != "") {
		cleanedDir := filepath.Clean(src.Directory)
		if strings.Contains(cleanedDir, "/") || (strings.Contains(cleanedDir, "\\")) {
			return fmt.Errorf("%q is not a valid directory, it must not contain a directory separator", src.Directory)
		}
	}
	return nil
}

patch:
func validateVolume(src *v1.GitRepoVolumeSource) error {
	if err := validateNonFlagArgument(src.Repository, "repository"); err != nil {
		return err
	}
	if err := validateNonFlagArgument(src.Revision, "revision"); err != nil {
		return err
	}
	if err := validateNonFlagArgument(src.Directory, "directory"); err != nil {
		return err
	}
	// Additional validation to prevent path traversal
	if src.Directory != "" {
		if filepath.IsAbs(src.Directory) {
			return fmt.Errorf("directory %q must be a relative path", src.Directory)
		}
		if strings.Contains(src.Directory, "..") {
			return fmt.Errorf("directory %q must not contain '..'", src.Directory)
		}
		// Normalize the path and check again
		cleaned := filepath.Clean(src.Directory)
		if strings.HasPrefix(cleaned, "..") || cleaned == ".." {
			return fmt.Errorf("directory %q resolves to a path outside the working directory", src.Directory)
		}
	}
	return nil
}

