	if redirect == "" {
		return false
	}

	// Decode URL-encoded characters to prevent bypass via encoding
	decodedRedirect, err := url.QueryUnescape(redirect)
	if err != nil {
		// If decoding fails, reject the redirect as it may be maliciously encoded
		logger.Printf("Rejecting invalid redirect %q: failed to decode URL", redirect)
		return false
	}

	// Check for whitespace characters that could be used to bypass validation
	// This includes space, tab, newline, carriage return, vertical tab, form feed, etc.
	for _, r := range decodedRedirect {
		if r <= ' ' {
			// ASCII control characters and space (0x00-0x20) are considered whitespace
			// This avoids the need for unicode import while still catching common bypass chars
			logger.Printf("Rejecting invalid redirect %q: contains whitespace character", redirect)
			return false
		}
	}

	switch {
	case strings.HasPrefix(decodedRedirect, "/") && !strings.HasPrefix(decodedRedirect, "//") && !strings.HasPrefix(decodedRedirect, "/\\"):
		return true
	case strings.HasPrefix(decodedRedirect, "http://") || strings.HasPrefix(decodedRedirect, "https://"):
		redirectURL, err := url.Parse(decodedRedirect)
		if err != nil {
			logger.Printf("Rejecting invalid redirect %q: scheme unsupported or missing", redirect)
			return false
		}
		redirectHostname := redirectURL.Hostname()

		for _, domain := range p.whitelistDomains {
			domainHostname, domainPort := splitHostPort(strings.TrimLeft(domain, "."))
			if domainHostname == "" {
				continue
			}

			if (redirectHostname == domainHostname) || (strings.HasPrefix(domain, ".") && strings.HasSuffix(redirectHostname, domainHostname)) {
				// the domain names match, now validate the ports
				// if the whitelisted domain's port is '*', allow all ports
				// if the whitelisted domain contains a specific port, only allow that port
				// if the whitelisted domain doesn't contain a port at all, only allow empty redirect ports ie http and https
				redirectPort := redirectURL.Port()
				if (domainPort == "*") ||
					(domainPort == redirectPort) ||
					(domainPort == "" && redirectPort == "") {
					return true
				}
			}
		}

		logger.Printf("Rejecting invalid redirect %q: domain / port not in whitelist", redirect)
		return false
	default:
		logger.Printf("Rejecting invalid redirect %q: not an absolute or relative URL", redirect)
		return false
	}
}

