func isRepositoryGitPath(path string) bool {
	// Normalize the path to handle various representations
	normalizedPath := filepath.ToSlash(filepath.Clean(path))

	// Check for exact .git directory
	if strings.HasSuffix(normalizedPath, "/.git") || normalizedPath == ".git" {
		return true
	}

	// Check for .git directory with trailing slash
	if strings.Contains(normalizedPath, "/.git/") {
		return true
	}

	// Windows-specific checks
	if runtime.GOOS == "windows" {
		// Handle backslash separators
		if strings.HasSuffix(path, "\\.git") || path == ".git" {
			return true
		}
		if strings.Contains(path, "\\.git\\") {
			return true
		}
		// Windows treats ".git." the same as ".git"
		if strings.HasSuffix(path, ".git.") {
			return true
		}
		if strings.Contains(path, ".git./") || strings.Contains(path, ".git.\\") {
			return true
		}
	}

	// Additional checks for common Git metadata files that indicate a Git repo
	gitMetadataFiles := []string{
		"/.git/config",
		"/.git/HEAD",
		"/.git/index",
		"/.git/objects/",
		"/.git/refs/",
	}

	for _, gitFile := range gitMetadataFiles {
		if strings.Contains(normalizedPath, gitFile) {
			return true
		}
	}

	return false
}

