func isLoopbackURI(requested *url.URL, registeredURI string) bool {
	registered, err := url.Parse(registeredURI)
	if err != nil {
		return false
	}

	// Only allow loopback redirects if the registered URI is also a loopback URI
	if registered.Scheme != "http" || !isLoopbackAddress(registered.Host) {
		return false
	}

	// For loopback URIs, we must ensure the requested URI matches the registered URI exactly
	// except for query parameters and fragments which should be ignored for matching purposes
	if requested.Scheme != "http" || !isLoopbackAddress(requested.Host) {
		return false
	}

	// Extract host and port from both URIs for comparison
	requestedHost, requestedPort, _ := net.SplitHostPort(requested.Host)
	if requestedPort == "" {
		requestedPort = "80" // default HTTP port
	}
	registeredHost, registeredPort, _ := net.SplitHostPort(registered.Host)
	if registeredPort == "" {
		registeredPort = "80" // default HTTP port
	}

	// Normalize loopback hosts to ensure consistent comparison
	if requestedHost == "localhost" || requestedHost == "::1" || strings.HasPrefix(requestedHost, "127.") {
		requestedHost = "127.0.0.1"
	}
	if registeredHost == "localhost" || registeredHost == "::1" || strings.HasPrefix(registeredHost, "127.") {
		registeredHost = "127.0.0.1"
	}

	// The requested URI must have the same host and port as the registered URI
	// and the same path
	if requestedHost == registeredHost && requestedPort == registeredPort && requested.Path == registered.Path {
		return true
	}

	return false
}

