import re

def deny_uploads_containing_script_tag(uploaded_file):
    # Define comprehensive patterns that could lead to XSS
    dangerous_patterns = [
        br'<script',
        br'on\w+\s*=',  # Matches onload=, onclick=, etc.
        br'javascript:',
        br'data:text/html',
        br'<iframe',
        br'<object',
        br'<embed',
        br'<svg.*on\w+',
        br'<img.*on\w+',
    ]
    compiled_patterns = [re.compile(pattern, re.IGNORECASE) for pattern in dangerous_patterns]

    buffer = b''
    for chunk in uploaded_file.chunks(2048):
        buffer += chunk
        # Process full buffer but keep last 100 bytes to handle cross-chunk matches
        if len(buffer) > 100:
            scan_part = buffer[:-100]
            buffer = buffer[-100:]
        else:
            scan_part = buffer
            buffer = b''

        for pattern in compiled_patterns:
            if pattern.search(scan_part.lower()):
                raise ValidationError(_("File contains forbidden scripting content"))

    # Check remaining buffer
    if buffer:
        for pattern in compiled_patterns:
            if pattern.search(buffer.lower()):
                raise ValidationError(_("File contains forbidden scripting content"))

