module.exports = function (packageName, { registry = '', timeout = null } = {}) {
    try {
        // Validate packageName to conform to npm naming conventions
        if (typeof packageName !== 'string' || !/^[a-zA-Z0-9._-]+$/.test(packageName)) {
            return null;
        }

        // Validate registry URL if provided
        let registryUrl = null;
        if (registry) {
            try {
                registryUrl = new URL(registry);
                if (!['http:', 'https:'].includes(registryUrl.protocol)) {
                    return null;
                }
            } catch (urlErr) {
                return null;
            }
        }

        const childProcess = require('child_process');
        const args = ['view', packageName, 'version'];
        if (registryUrl) {
            args.push('--registry', registryUrl.href);
        }

        const config = {
            stdio: ['pipe', 'pipe', 'ignore']
        };

        if (timeout) {
            config.timeout = timeout;
        }

        const result = childProcess.spawnSync('npm', args, config);

        if (result.error) {
            return null;
        }

        let version = result.stdout;
        if (version) {
            return version.toString().trim().replace(/^\n*/, '').replace(/\n*$/, '');
        } else {
            return null;
        }

    } catch (err) {
        return null;
    }
}

