function template(literal, data) {
  // Replace template placeholders with actual data values safely
  // Match ${identifier} patterns where identifier is a valid property name
  return literal.replace(/\$\{([^}]+)\}/g, function(match, key) {
    // Trim whitespace and validate key contains only valid property name characters
    var prop = key.trim();
    // Only allow alphanumeric characters, underscore, and dot for nested properties
    if (!/^[a-zA-Z_$][a-zA-Z0-9_$]*(\.[a-zA-Z_$][a-zA-Z0-9_$]*)*$/.test(prop)) {
      throw new Error('Invalid template variable: ' + prop);
    }

    // Safely resolve nested properties
    var parts = prop.split('.');
    var current = data;
    for (var i = 0; i < parts.length; i++) {
      var part = parts[i];
      // Prevent access to prototype or constructor
      if (part === '__proto__' || part === 'constructor' || part === 'prototype') {
        throw new Error('Access to restricted property: ' + part);
      }
      if (current == null || typeof current !== 'object') {
        return '';
      }
      current = current[part];
    }

    // Return string representation of the value
    return current != null ? String(current) : '';
  });
}

