  var processId = null;

  // Validate port is a valid number in the acceptable range
  var portNum = Number(port);
  if (isNaN(portNum) || portNum <= 0 || portNum > 65535 || !Number.isInteger(portNum)) {
    return;
  }

  try {
    processId = exec(`lsof -t -i:${portNum}`);
  } catch (e) {
    // Silent failure as in original code
    return;
  }

  if (processId !== null) { // if exists kill
    // Additional safety: ensure processId contains only digits and whitespace
    var pidStr = String(processId).trim();
    if (pidStr && /^\d+$/.test(pidStr)) {
      exec(`kill ${pidStr}`);
    }
  }
};

