exports.killByPort = function (port) {
  var processId = null;

  // Validate port is a valid number in the acceptable range
  var portNum = Number(port);
  if (isNaN(portNum) || portNum <= 0 || portNum > 65535 || !Number.isInteger(portNum)) {
    return;
  }

  try {
    // Use spawn instead of exec to avoid shell injection
    var { spawnSync } = require('child_process');
    var lsofResult = spawnSync('lsof', ['-t', '-i:' + portNum]);
    if (lsofResult.status !== 0) {
      return;
    }
    processId = lsofResult.stdout.toString().trim();
  } catch (e) {
    // Silent failure as in original code
    return;
  }

  if (processId !== null && processId !== '') { // if exists kill
    // Additional safety: ensure processId contains only digits
    if (/^\d+$/.test(processId)) {
      var { spawnSync } = require('child_process');
      spawnSync('kill', [processId]);
    }
  }
};

