module.execute = function(arrParams) {
    return new Promise(function(resolve, reject) {
        var jarPath = path.join(__dirname, 'jar', 'key-sender.jar');

        // Validate arrParams to ensure they don't contain dangerous characters
        for (var i = 0; i < arrParams.length; i++) {
            if (typeof arrParams[i] !== 'string') {
                return reject(new Error('All parameters must be strings'));
            }
            // Allow only safe characters (alphanumeric, spaces, basic punctuation)
            // Block shell metacharacters that could enable command injection
            if (/[^a-zA-Z0-9\-_.,:\/\\ ]/.test(arrParams[i])) {
                return reject(new Error('Parameter contains invalid characters'));
            }
        }

        // Build arguments array for execFile to avoid shell interpretation
        var args = ['-jar', jarPath];
        args = args.concat(arrParams);

        // Get command line options and parse them into individual arguments
        var cmdLineOptions = module.getCommandLineOptions().trim();
        if (cmdLineOptions) {
            // Split options while preserving quoted strings
            var optionArgs = cmdLineOptions.match(/(?:[^"]\S*|".+?")+/g) || [];
            // Remove quotes from each argument
            for (var j = 0; j < optionArgs.length; j++) {
                optionArgs[j] = optionArgs[j].replace(/^"|"$/g, '');
                // Validate option arguments as well
                if (/[^a-zA-Z0-9\-_.,:\/\\ =]/.test(optionArgs[j])) {
                    return reject(new Error('Command line option contains invalid characters'));
                }
            }
            args = args.concat(optionArgs);
        }

        return execFile('java', args, {}, function(error, stdout, stderr) {
            if (error == null) {
                resolve(stdout, stderr);
            } else {
                reject(error, stdout, stderr);
            }
        });
    });
};

