trimvideo: (input, start, duration, output) => {
  const path = require("path");
  const { spawn } = require("child_process");
  return new Promise(function(resolve, reject) {
    if (fs.existsSync(input)) {
      // Validate inputs to prevent command injection
      if (!/^[0-9:.]+$/.test(start)) {
        reject(new Error("Invalid start time format"));
        return;
      }
      if (!/^[0-9:.]+$/.test(duration)) {
        reject(new Error("Invalid duration format"));
        return;
      }

      // Validate and sanitize file paths
      // Check for dangerous characters in output filename
      if (/[\s;|&$`"'<>]/.test(output)) {
        reject(new Error("Invalid output filename"));
        return;
      }

      // Resolve and normalize file paths
      const resolvedInput = path.resolve(input);
      const resolvedOutput = path.resolve(output + ".mp4");

      // Additional check: ensure resolved input matches original input file existence
      if (!fs.existsSync(resolvedInput)) {
        reject(new Error("ffmpegdotjs could not find file"));
        return;
      }

      // Use spawn instead of exec to avoid shell interpretation
      const ffmpegArgs = [
        "-hide_banner",
        "-loglevel", "quiet",
        "-ss", start,
        "-i", resolvedInput,
        "-t", duration,
        "-c", "copy",
        "-y",
        resolvedOutput
      ];

      const ffmpegProcess = spawn("ffmpeg", ffmpegArgs);

      ffmpegProcess.on("error", (error) => {
        reject(error);
      });

      ffmpegProcess.on("close", (code) => {
        if (code !== 0) {
          reject(new Error(`ffmpeg process exited with code ${code}`));
          return;
        }
        resolve(resolvedOutput);
      });
    } else {
      reject(new Error("ffmpegdotjs could not find file"));
    }
  });
},

