var main = function(req, res) {
        var reqUrl = req.url; 
        //记录请求信息
        logger.http(req, res);

        //使用url解析模块获取url中的路径名 
        var pathName = url.parse(reqUrl).pathname;

        // Reject paths containing directory traversal sequences
        if (pathName.indexOf('..') !== -1) {
            res.writeHead(404, {
                "Content-Type": "text/html"
            });
            res.end('<h1>404 Not Found</h1>');
            return;
        }

        //补全文件路径
        if (path.extname(pathName) == "") {

            if(!/\/$/.test(pathName)){
                pathName += '/';
            }

            pathName += argvs.getDefault();
        }

        //使用路径解析模块,组装实际文件路径 
        var filePath = path.join(argvs.getPath(), pathName);

        // Resolve to absolute path and validate it's within the allowed directory
        var resolvedPath = path.resolve(filePath);
        var rootPath = path.resolve(argvs.getPath());

        // Normalize paths to handle trailing slashes consistently
        if (!resolvedPath.startsWith(rootPath + path.sep) && resolvedPath !== rootPath) {
            res.writeHead(404, {
                "Content-Type": "text/html"
            });
            res.end('<h1>404 Not Found</h1>');
            return;
        }

        //判断文件是否存在 
