patch:
var cleanUrl = function(url) { 
	// Decode the URL to handle encoded characters
	url = decodeURIComponent(url);

	// Resolve the path to get an absolute path
	// We need a base directory to resolve against - using process.cwd() as a reasonable default
	// In a real application, this should be configured to the intended document root
	var basePath = process.cwd();
	var resolvedPath = require('path').resolve(basePath, url);

	// Ensure the resolved path is within the base path to prevent directory traversal
	if (!resolvedPath.startsWith(basePath + require('path').sep) && resolvedPath !== basePath) {
		throw new Error('Invalid path: attempted directory traversal');
	}

	return resolvedPath;
};

