  var toEvaluate = expression.replace(new RegExp(unit, "gi"), "")
  var result

  try {
    // Use a safe math evaluator instead of eval
    result = safeMathEval(toEvaluate)
  }
  catch (e) {
    return functionIdentifier + "(" + expression + ")"
