func PDFHasImage(path string) bool {
	cmd := exec.Command("pdffonts", "-l", "5", path)
	out, err := cmd.Output()
	if err != nil {
		log.Println(err)
		return false
	}

	// Split output into lines
	lines := strings.Split(string(out), "\n")
	// Skip header lines (first two lines)
	if len(lines) < 3 {
		return true // No font entries
	}

	fontLines := lines[2:]
	for _, line := range fontLines {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		// Extract first field (font name)
		fields := strings.Fields(line)
		if len(fields) > 0 && fields[0] != "" {
			// At least one font found
			return false
		}
	}

	// No valid font entries found
	return true
}

