def _extract_packages_archive(work_dir):
    package_file = os.path.join(work_dir, "packages.tar")
    if not os.path.exists(package_file):
        return

    work_dir = os.path.abspath(work_dir)
    tar = tarfile.open(package_file)
    try:
        for tarinfo in tar:
            # Resolve the final path where the file would be extracted
            dest_path = os.path.abspath(os.path.join(work_dir, tarinfo.name))
            # Ensure the destination is within work_dir
            if not dest_path.startswith(work_dir + os.sep) and dest_path != work_dir:
                raise ValueError("Attempted path traversal in tar file: {}".format(tarinfo.name))
            tar.extract(tarinfo, work_dir)
    finally:
        tar.close()

    if '' not in sys.path:
        sys.path.insert(0, '')

