func redirectTrailingSlash(c *Context) {
	req := c.Request
	p := req.URL.Path
	prefixHeader := c.Request.Header.Get("X-Forwarded-Prefix")
	if prefixHeader != "" {
		// Validate and sanitize X-Forwarded-Prefix
		prefix := path.Clean(prefixHeader)
		// Only accept non-empty, absolute paths that remain absolute after cleaning
		if prefix != "." && strings.HasPrefix(prefix, "/") && isValidPathPrefix(prefix) {
			prefix = url.QueryEscape(prefix)
			prefix = strings.ReplaceAll(prefix, "%2F", "/")
			p = prefix + "/" + req.URL.Path
		}
	}
	req.URL.Path = p + "/"
	if length := len(p); length > 1 && p[length-1] == '/' {
		req.URL.Path = p[:length-1]
	}
	redirectRequest(c)
}

// isValidPathPrefix checks if the prefix is a safe, normalized absolute path
func isValidPathPrefix(p string) bool {
	if len(p) == 0 || p[0] != '/' {
		return false
	}
	// Reject paths containing null bytes, control chars, or spaces
	for _, r := range p {
		if r < ' ' || r == 0x7f {
			return false
		}
	}
	// Ensure path.Clean doesn't change the prefix (i.e., no '..' or '.' tricks)
	if path.Clean(p) != p {
		return false
	}
	return true
}

