// canAcceptRsyncArgs validates rsync command arguments to prevent dangerous options
func canAcceptRsyncArgs(args []string) bool {
	// List of blocked/dangerous rsync options
	blockedOptions := map[string]bool{
		"--rsync-path":       true,
		"--rsh":              true,
		"-e":                 true,
		"--include-from":     true,
		"--exclude-from":     true,
		"--read-batch":       true,
		"--write-batch":      true,
		"--only-write-batch": true,
		"--files-from":       true,
		"--list-only":        true,
		"--protect-args":     true,
		"-s":                 true,
	}

	for i, arg := range args {
		// Skip the last argument as it's the destination path
		if i == len(args)-1 {
			continue
		}

		// Check for blocked options
		if strings.HasPrefix(arg, "-") {
			// Handle options with values like --option=value
			baseArg := arg
			if equalIndex := strings.Index(arg, "="); equalIndex != -1 {
				baseArg = arg[:equalIndex]
			}

			// Check if this is a blocked option
			if blockedOptions[baseArg] {
				return false
			}

			// For short options like -avz, check each character
			if len(arg) > 1 && arg[1] != '-' {
				for _, char := range arg[1:] {
					shortOpt := "-" + string(char)
					if blockedOptions[shortOpt] {
						return false
					}
				}
			}
		} else {
			// Non-option arguments (source paths)
			// Block paths containing .. or ~ which could escape the home directory
			// Also block absolute paths
			if strings.Contains(arg, "..") || strings.Contains(arg, "~") || strings.HasPrefix(arg, "/") {
				return false
			}
		}
	}

	return true
}

