getInfo: function () {
  var self = this;
  var commandParts = this.constructGetInfoCommand();
  var promise = new Promise(function (resolve, reject) {
    var child = require('child_process').spawn(commandParts[0], commandParts.slice(1));
    var stdout = '';
    var stderr = '';

    child.stdout.on('data', function (data) {
      stdout += data.toString();
    });

    child.stderr.on('data', function (data) {
      stderr += data.toString();
    });

    child.on('error', function (err) {
      return reject({
        message: "Failed to get PDF'S information",
        error: err,
        stdout: stdout,
        stderr: stderr
      });
    });

    child.on('close', function (code) {
      if (code !== 0) {
        var err = new Error('pdfinfo exited with code ' + code);
        return reject({
          message: "Failed to get PDF'S information",
          error: err,
          stdout: stdout,
          stderr: stderr
        });
      }
      return resolve(self.parseGetInfoCommandOutput(stdout));
    });
  });
  return promise;
}

