function isValidServerHostname(hostname: string): boolean {
  // Remove brackets from IPv6 addresses if present
  let cleanHostname = hostname.replace(/^\[|\]$/g, '');

  // Reject empty hostnames
  if (!cleanHostname || cleanHostname.trim() === "") {
    return false;
  }

  // Check if it's an IP address (IPv4 or IPv6)
  if (isIPAddress(cleanHostname)) {
    // Reject loopback addresses
    if (isLoopbackIP(cleanHostname)) {
      return false;
    }

    // Reject private IP addresses
    if (isPrivateIP(cleanHostname)) {
      return false;
    }

    // Reject link-local addresses
    if (isLinkLocalIP(cleanHostname)) {
      return false;
    }

    // Reject multicast and other special addresses
    if (isSpecialUseIP(cleanHostname)) {
      return false;
    }
  } else {
    // It's a hostname, not an IP
    const lowerHost = cleanHostname.toLowerCase();

    // Reject localhost and local domains
    if (lowerHost === "localhost" || 
        lowerHost.endsWith(".local") || 
        lowerHost.endsWith(".localhost") ||
        lowerHost === "localhost.localdomain") {
      return false;
    }

    // Basic hostname validation
    if (!/^[a-zA-Z0-9][a-zA-Z0-9.-]*[a-zA-Z0-9]$/.test(cleanHostname)) {
      return false;
    }

    // Ensure it has at least one dot (to avoid single-word hostnames that might resolve internally)
    if (!cleanHostname.includes(".")) {
      return false;
    }
  }

  return true;
}

