function isIPv4Address(ip: string): boolean {
  if (ip.includes(":")) return false;
  const parts = ip.split(".");
  if (parts.length !== 4) return false;

  for (const part of parts) {
    if (!/^\d+$/.test(part)) return false;
    const num = parseInt(part, 10);
    if (num < 0 || num > 255) return false;
  }

  return true;
}

function isIPv6Address(ip: string): boolean {
  if (!ip.includes(":")) return false;
  if (ip.includes(".")) return false; // IPv4-mapped IPv6 would have dots

  try {
    // Basic IPv6 validation
    const normalized = ip.toLowerCase();
    // Allow compressed format (::)
    if (normalized === "::") return true;

    // Count colons to ensure valid format
    const colonCount = (normalized.match(/:/g) || []).length;
    if (colonCount < 2 || colonCount > 7) return false;

    // Split by colons and validate each part
    const parts = normalized.split(":");
    for (const part of parts) {
      if (part === "") continue; // Empty parts are allowed in compressed format
      if (!/^[0-9a-f]{1,4}$/.test(part)) return false;
    }

    return true;
  } catch {
    return false;
  }
