    const parts = ip.split(".").map(Number);
    return parts[0] === 127;
  }

  if (isIPv6Address(ip)) {
    const normalized = ip.toLowerCase().replace(/^\[|\]$/g, '');
    return normalized === "::1" || normalized.startsWith("::1:") || normalized.endsWith(":::1");
