// isValidNodeName checks if a node name contains only valid characters.
// Based on Consul's node naming rules: letters, digits, hyphens, underscores, and periods.
func isValidNodeName(name string) bool {
	if name == "" {
		return false
	}
	for _, r := range name {
		if !(unicode.IsLetter(r) || unicode.IsDigit(r) || r == '-' || r == '_' || r == '.') {
			return false
		}
	}
	return true
}

// isValidSegmentName checks if a segment name contains only valid characters.
// Network segments typically follow similar naming constraints as node names.
func isValidSegmentName(name string) bool {
	if name == "" {
		return true // empty segment is allowed (default segment)
	}
	for _, r := range name {
		if !(unicode.IsLetter(r) || unicode.IsDigit(r) || r == '-' || r == '_') {
			return false
		}
	}
	return true
}

