const { isAbsolute, parse } = require('path');

module.exports = path => {
  // Sanitize path to prevent directory traversal
  if (typeof path !== 'string') {
    throw new TypeError('Path must be a string');
  }

  // Remove any \0 null bytes
  if (path.includes('\0')) {
    throw new Error('Path contains null bytes');
  }

  // Check for and reject paths containing .. that could lead to traversal
  // This includes Windows drive-relative paths like C:../foo
  const normalizedPath = path.replace(/\\/g, '/');

  // Reject paths that contain .. in any form that could cause traversal
  if (/^\.\.[\/]|^[A-Za-z]:\.\.\//.test(normalizedPath) || 
      /(?:^|[^A-Za-z])[A-Za-z]:\.\./.test(path) ||
      /(?:^|\/)\.\.\/(?!$)/.test(normalizedPath)) {
    throw new Error('Path contains invalid .. sequence');
  }

  // Additional check for Windows drive letter paths that don't have backslashes
  // but could still cause issues (e.g., "C:foo" vs "C:\\foo")
  if (process.platform === 'win32') {
    if (/^[A-Za-z]:[^\\/]/.test(path)) {
      // Drive-relative path without separator - treat as relative to drive's cwd
      // This is dangerous, so we reject it
      throw new Error('Drive-relative paths without separator are not allowed');
    }
  }

  let r = ''
  let remainingPath = path

  while (isAbsolute(remainingPath)) {
    // windows will think that //x/y/z has a "root" of //x/y/
    const root = remainingPath.charAt(0) === '/' ? '/' : parse(remainingPath).root
    if (!root) break;
    remainingPath = remainingPath.substr(root.length)
    r += root
  }

  return [r, remainingPath]
}

