        directory = os.path.realpath(directory)
        # Ensure directory ends with a path separator to prevent partial matches
        if not directory.endswith(os.sep):
            directory += os.sep
        # Use commonpath for proper path-based comparison instead of string prefix
        try:
            if os.path.commonpath([full_path, directory]) != os.path.commonpath([directory]):
