// addGroupsToSession adds the user's actual GitLab groups to session.Groups
func (p *GitLabProvider) addGroupsToSession(ctx context.Context, s *sessions.SessionState) {
	// If no groups are configured for restriction, skip fetching user groups
	if len(p.Groups) == 0 {
		return
	}

	// Fetch the actual groups the user belongs to from GitLab
	req, err := http.NewRequestWithContext(ctx, "GET", p.getGroupsURL(), nil)
	if err != nil {
		log.Printf("Warning: failed to create groups request: %v", err)
		return
	}

	req.Header.Set("User-Agent", userAgent)
	req.Header.Set("Authorization", fmt.Sprintf("Bearer %s", s.AccessToken))

	resp, err := p.Client.Do(req)
	if err != nil {
		log.Printf("Warning: failed to fetch user groups from GitLab: %v", err)
		return
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		log.Printf("Warning: gitlab groups endpoint returned status %d", resp.StatusCode)
		return
	}

	body, err := io.ReadAll(resp.Body)
	if err != nil {
		log.Printf("Warning: failed to read groups response body: %v", err)
		return
	}

	var groups []map[string]interface{}
	if err := json.Unmarshal(body, &groups); err != nil {
		log.Printf("Warning: failed to unmarshal groups response: %v", err)
		return
	}

