def _clean_code(self, code: str) -> str:
    """
    A method to clean the code to prevent malicious code execution

    Args:
        code(str): A python code

    Returns (str): Returns a Clean Code String

    """

    tree = ast.parse(code)

    new_body = []

    # clear recent optional dependencies
    self._additional_dependencies = []

    def _check_node(node):
        """Recursively check AST nodes for dangerous constructs."""
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            self._check_imports(node)
            return False  # exclude imports from final code
        if self._is_df_overwrite(node):
            return False
        # Check for dangerous function calls
        if isinstance(node, ast.Call):
            if isinstance(node.func, ast.Name):
                if node.func.id in ('eval', 'exec', 'compile', '__import__'):
                    raise ValueError(f"Disallowed function call: {node.func.id}")
            elif isinstance(node.func, ast.Attribute):
                # Check for getattr(obj, 'dangerous_attr'), obj.__dict__, etc.
