                if attr_name in ('__dict__', '__class__', '__bases__', '__mro__',
                                 '__subclasses__', '_exitfunc', 'system', 'popen',
                                 'spawn', 'fork', 'exec', 'eval', 'compile'):
                    raise ValueError(f"Disallowed attribute access: {attr_name}")
