func newRequestFromQuery(settings *backend.DataSourceInstanceSettings, customSettings dataSourceSettings, query dataSourceQuery) (*http.Request, error) {
	baseURL, err := url.Parse(settings.URL)
	if err != nil {
		return nil, err
	}

	// Validate that query.Path is a relative path and doesn't contain scheme or authority
	if query.Path != "" {
		pathURL, err := url.Parse(query.Path)
		if err != nil {
			return nil, err
		}
		// Reject if the path contains scheme, host, or user info
		if pathURL.Scheme != "" || pathURL.Host != "" || pathURL.User != nil {
			return nil, fmt.Errorf("invalid path: must be a relative path without scheme, host, or user info")
		}
	}

	// Resolve the path against the base URL
	u := baseURL.ResolveReference(&url.URL{Path: query.Path})

	// Ensure we're still using the original scheme and host
	if u.Scheme != baseURL.Scheme || u.Host != baseURL.Host {
		return nil, fmt.Errorf("invalid path: cannot change scheme or host")
