// publicKeysEqual compares two public keys for equality.
// It handles different key types (RSA, ECDSA, Ed25519) appropriately.
func publicKeysEqual(a, b crypto.PublicKey) bool {
	if a == nil || b == nil {
		return a == b
	}

	// Handle RSA keys
	if rsaA, ok := a.(*rsa.PublicKey); ok {
		if rsaB, ok := b.(*rsa.PublicKey); ok {
			return rsaA.N.Cmp(rsaB.N) == 0 && rsaA.E == rsaB.E
		}
		return false
	}

	// Handle ECDSA keys
	if ecdsaA, ok := a.(*ecdsa.PublicKey); ok {
		if ecdsaB, ok := b.(*ecdsa.PublicKey); ok {
			return ecdsaA.X.Cmp(ecdsaB.X) == 0 && ecdsaA.Y.Cmp(ecdsaB.Y) == 0 &&
				ecdsaA.Curve.Params().Name == ecdsaB.Curve.Params().Name
		}
		return false
	}

	// Handle Ed25519 keys
	if edA, ok := a.(ed25519.PublicKey); ok {
		if edB, ok := b.(ed25519.PublicKey); ok {
			return bytes.Equal(edA, edB)
		}
		return false
	}

	// For other key types, fall back to deep comparison
	return reflect.DeepEqual(a, b)
}

