function escapeShellArg(arg) {
  if (arg === null || arg === undefined) {
    return "''";
  }
  const str = String(arg);
  // Remove null bytes which can be used for command injection
  const sanitized = str.replace(/\x00/g, '');
  return "'" + sanitized.replace(/'/g, "'\\''") + "'";
}

