			c.desc.Size = int64(cl)
		}
		if c.desc.Digest == "" {
			c.desc.Digest, _ = digest.Parse(mc.header.Get("Docker-Content-Digest"))
		}
		c.setRateLimit(mc.header)
	}
	// If we have raw body and a digest, verify immediately
	if len(mc.raw) > 0 && c.desc.Digest != "" {
		// Handle signed manifest case by attempting to parse it first
		if c.desc.MediaType == mediatype.Docker1ManifestSigned || c.desc.MediaType == "" {
			var tempMt struct {
				SchemaVersion int           `json:"schemaVersion,omitempty"`
				Signatures    []interface{} `json:"signatures,omitempty"`
			}
			if err := json.Unmarshal(mc.raw, &tempMt); err == nil &&
				tempMt.SchemaVersion == 1 && len(tempMt.Signatures) > 0 {
				// This appears to be a signed manifest, verify using canonical form
				var signedMan schema1.SignedManifest
				if err := json.Unmarshal(mc.raw, &signedMan); err == nil && len(signedMan.Canonical) > 0 {
					computedDigest := c.desc.DigestAlgo().FromBytes(signedMan.Canonical)
					if c.desc.Digest != computedDigest {
						return nil, fmt.Errorf("manifest digest mismatch, expected %s, computed %s", c.desc.Digest, computedDigest)
					}
				} else {
					// Fall back to raw body verification if canonical form is not available
					computedDigest := c.desc.DigestAlgo().FromBytes(mc.raw)
					if c.desc.Digest != computedDigest {
						return nil, fmt.Errorf("manifest digest mismatch, expected %s, computed %s", c.desc.Digest, computedDigest)
					}
				}
			} else {
				// Not a signed manifest, verify using raw body
				computedDigest := c.desc.DigestAlgo().FromBytes(mc.raw)
				if c.desc.Digest != computedDigest {
					return nil, fmt.Errorf("manifest digest mismatch, expected %s, computed %s", c.desc.Digest, computedDigest)
				}
			}
		} else {
			// Not a signed manifest, verify using raw body
			computedDigest := c.desc.DigestAlgo().FromBytes(mc.raw)
			if c.desc.Digest != computedDigest {
				return nil, fmt.Errorf("manifest digest mismatch, expected %s, computed %s", c.desc.Digest, computedDigest)
			}
		}
	}
	if mc.orig != nil {
		return fromOrig(c, mc.orig)
	}
	return fromCommon(c)
