function cpOptsInData(data, opts) {
  _OPTS.forEach(function (p) {
    if (typeof data[p] != 'undefined') {
      // Disallow setting the root opt for includes via a passed data obj
      // Unsanitized, parameterized use of `render` could allow the
      // include directory to be reset, opening up the possibility of
      // remote code execution
      if (p == 'root') {
        return;
      }
      // Validate input types for security-sensitive options
      switch (p) {
        case 'cache':
        case 'strict':
          if (typeof data[p] !== 'boolean') {
            return;
          }
          break;
        case 'filename':
        case 'context':
        case 'compileDebug':
        case '_with':
          // Allow these properties but ensure they are of expected types
          // filename should be string
          if (p === 'filename' && typeof data[p] !== 'string') {
            return;
          }
          // context should be object
          if (p === 'context' && typeof data[p] !== 'object') {
            return;
          }
          // compileDebug and _with should be boolean
          if ((p === 'compileDebug' || p === '_with') && typeof data[p] !== 'boolean') {
            return;
          }
          break;
        default:
          // For any other properties, only allow primitive types
          if (typeof data[p] === 'object' || typeof data[p] === 'function') {
            return;
          }
      }
      opts[p] = data[p];
    }
  });
}

