function buildURL (source, reqBase) {
  const dest = new URL(source, reqBase)

  // if base is specified, source url should not override it
  if (reqBase) {
    const base = new URL(reqBase)
    // Normalize base path to end with / for proper prefix comparison
    let basePath = base.pathname
    if (!basePath.endsWith('/')) {
      basePath += '/'
    }

    // Normalize dest path to ensure consistent comparison
    let destPath = dest.pathname
    if (!destPath.endsWith('/') && destPath !== basePath.slice(0, -1)) {
      // Only add trailing slash if dest is a directory-like path
      // But for comparison purposes, we need to handle both cases
    }

    // Check that origins match and destination path is within base path
    // Special case: if dest.pathname exactly equals base.pathname without trailing slash
    const isValidPath = dest.pathname === base.pathname || dest.pathname.startsWith(basePath)

    if (dest.origin !== base.origin || !isValidPath) {
      throw new Error('source must be a relative path string')
    }
  }

  return dest
}

