export function handler (type, name, fn) {
  // Prevent prototype pollution by ensuring name is a safe property
  if (typeof name !== 'string' || name === '__proto__' || name === 'constructor' || name === 'prototype') {
    return undefined;
  }

  // Additional safety: ensure we're not accessing inherited properties
  if (name in Object.prototype) {
    return undefined;
  }

  if (arguments.length > 2) {
    // Only set if handlers[type] exists and name is safe
    if (!handlers[type]) {
      handlers[type] = {};
    }
    handlers[type][name] = fn;
  }

  return handlers[type] && handlers[type][name];
}

