const { escapeRegExp } = require('lodash');
const { size, isString } = require('lodash');

// Add URL encoding variants for secrets that might appear in URLs
const getUrlEncodedVariants = (secret) => {
  const variants = new Set();
  variants.add(secret);

  // Add standard URL encoding
  variants.add(encodeURIComponent(secret));

  // Add URL encoding with uppercase hex digits (some systems use uppercase)
  variants.add(encodeURIComponent(secret).replace(/%[0-9a-f]{2}/g, (match) => match.toUpperCase()));

  // Handle common URL encoding edge cases
  // Some systems encode spaces as + instead of %20
  if (secret.includes(' ')) {
    variants.add(encodeURIComponent(secret).replace(/%20/g, '+'));
    variants.add(encodeURIComponent(secret).replace(/%20/g, '+').replace(/%[0-9a-f]{2}/g, (match) => match.toUpperCase()));
  }

  return Array.from(variants);
};

